python3 << 'EOF'
# Find ralph_respond invocations in Director sessions and extract user messages
import json, glob, os, re
from collections import Counter

director_sessions = glob.glob('/home/ubuntu/.claude-account-*/projects/*director-98a1947f*/*.jsonl')
print(f"Found {len(director_sessions)} director sessions")

ralph_msgs = []
for p in director_sessions:
    sz = os.path.getsize(p)
    with open(p) as f:
        for line in f:
            try:
                e = json.loads(line)
                # Look at tool_use entries for ralph_respond
                msg = e.get('message', {}) if isinstance(e.get('message'), dict) else {}
                content = msg.get('content', [])
                if isinstance(content, list):
                    for c in content:
                        if isinstance(c, dict):
                            if c.get('type') == 'tool_use' and 'ralph_respond' in c.get('name',''):
                                inp = c.get('input', {})
                                ralph_msgs.append({
                                    'ts': e.get('timestamp'),
                                    'session': os.path.basename(p)[:8],
                                    'msg': str(inp)[:300]
                                })
            except: pass

print(f"Total ralph_respond invocations: {len(ralph_msgs)}")
# Sort and show first 30
ralph_msgs.sort(key=lambda x: x.get('ts',''))
print("\n=== First 30 ralph_respond (Director→user messages) ===")
for m in ralph_msgs[:30]:
    print(f"{m['ts']}  {m['session']}  {m['msg'][:200]}")

print("\n=== Last 20 ===")
for m in ralph_msgs[-20:]:
    print(f"{m['ts']}  {m['session']}  {m['msg'][:200]}")
EOF

